//{title: "2-1",unlock: null,"id": "chapterX_episodeX",script:`[]`}

const LAST_STORY_CHAPTER_KEY = "glassbeatLastStoryChapter";
const storyUrlParams = new URLSearchParams(location.search);
const requestedEpisodeId = storyUrlParams.get("episode");
const boss4EventStoryEntry =
  requestedEpisodeId === "chapter4_episode11"
  && storyUrlParams.get("source") === "boss4Event";

if (boss4EventStoryEntry) {
  document.body.classList.add("boss4EventStoryEntry");
}

let currentChapterIndex = Number(localStorage.getItem(LAST_STORY_CHAPTER_KEY) || 0);

function getVisibleChapterIndex(preferredIndex) {
  if (chapters[preferredIndex] && !chapters[preferredIndex].hidden) return preferredIndex;

  for (let index = Math.min(preferredIndex - 1, chapters.length - 1); index >= 0; index--) {
    if (!chapters[index].hidden) return index;
  }

  return chapters.findIndex(chapter => !chapter.hidden);
}

currentChapterIndex = getVisibleChapterIndex(currentChapterIndex);
let currentEpisodeIndex = null;
let currentLineIndex = 0;
let typingTimer = null;
let isTyping = false;
let fullText = "";
let introImageActive = false;
let introImageFading = false;
let introImageFadeTimer = null;
let currentEpisodeSource = "normal";
let episodeColumn = null;

const storyPage = document.getElementById("storyPage");
const readingOverlay = document.getElementById("readingOverlay");
const storyText = document.getElementById("storyText");
const chapterTitle = document.getElementById("chapterTitle");
const episodeList = document.getElementById("episodeList");
const researchRecordsButton = document.getElementById("researchRecordsButton");
const researchRecordsOverlay = document.getElementById("researchRecordsOverlay");
const researchRecordsList = document.getElementById("researchRecordsList");
let researchRecords = [];

function isChapter5Selected() {
  return chapters[currentChapterIndex]?.title === "硝子越しの残響";
}

function updateResearchRecordsButtonVisibility() {
  researchRecordsButton?.classList.toggle("hidden", !isChapter5Selected());
}

function showResearchRecord(record, selectedButton) {
  document.querySelectorAll(".researchRecordListItem.active").forEach(button => {
    button.classList.remove("active");
  });
  selectedButton?.classList.add("active");
  document.getElementById("researchRecordId").textContent = record?.id || "---";
  document.getElementById("researchRecordTitle").textContent = record?.title || "記録を選択してください";
  document.getElementById("researchRecordBody").textContent = String(record?.body || "")
    .split("/")
    .map(line => line.trim())
    .join("\n");
}

function renderResearchRecords() {
  if (!researchRecordsList) return;
  researchRecordsList.replaceChildren();
  researchRecords.forEach((record, index) => {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "researchRecordListItem";

    const id = document.createElement("span");
    id.className = "researchRecordListId";
    id.textContent = record.id;
    const title = document.createElement("span");
    title.className = "researchRecordListTitle";
    title.textContent = record.title;
    button.append(id, title);
    button.addEventListener("click", () => showResearchRecord(record, button));
    researchRecordsList.appendChild(button);

    if (index === 0) showResearchRecord(record, button);
  });
}

function loadResearchRecords() {
  const data = window.researchRecordsData || {};
  researchRecords = Array.isArray(data.records) ? data.records : [];
  renderResearchRecords();
}

function openResearchRecords() {
  if (!isChapter5Selected() || !researchRecordsOverlay) return;
  loadResearchRecords();
  researchRecordsOverlay.classList.remove("hidden");
  researchRecordsOverlay.setAttribute("aria-hidden", "false");
  document.body.classList.add("researchRecordsOpen");
  if (storyPage) storyPage.inert = true;
  document.getElementById("researchRecordsClose")?.focus();
}

function closeResearchRecords() {
  if (!researchRecordsOverlay) return;
  researchRecordsOverlay.classList.add("hidden");
  researchRecordsOverlay.setAttribute("aria-hidden", "true");
  document.body.classList.remove("researchRecordsOpen");
  if (storyPage) storyPage.inert = false;
  researchRecordsButton?.focus();
}

researchRecordsButton?.addEventListener("click", openResearchRecords);
document.getElementById("researchRecordsClose")?.addEventListener("click", closeResearchRecords);
researchRecordsOverlay?.addEventListener("click", event => {
  if (event.target === researchRecordsOverlay) closeResearchRecords();
});
document.addEventListener("keydown", event => {
  if (event.key === "Escape" && !researchRecordsOverlay?.classList.contains("hidden")) {
    closeResearchRecords();
  }
});

const song9StartSound = new Audio("sounds/startsound.mp3");
song9StartSound.volume = 0.9;

function getSaveData() {
  return JSON.parse(localStorage.getItem("rhythmGame") || "{}");
}

function getSong19MaxClearedDifficulty(saveData = getSaveData()) {
  const rawMaximum = saveData.song19MaxClearedDifficulty;
  const savedMaximum = Number(rawMaximum);
  if (rawMaximum !== null && rawMaximum !== "" && Number.isInteger(savedMaximum)) {
    return Math.max(-1, Math.min(2, savedMaximum));
  }

  // 最高難易度の保存前に作られたセーブデータを引き継ぐ。
  if (saveData.boss3UnlockChallengeCleared === true) {
    return Math.max(0, Math.min(2, Number(saveData.boss3UnlockChallengeDifficulty) || 0));
  }
  return -1;
}

function getCurrentPartnerId() {
  const saveData = getSaveData();
  return saveData.profile?.partner || "breaka";
}

function isEpisodeUnlocked(episode, previousEpisode = null) {
  if (!episode.unlock) return true;

  const requiredStoryId = episode.unlock.storyId || previousEpisode?.id;

  if (episode.unlock.type === "songPlayed") {
    return hasPlayedSong(episode.unlock.song);
  }
  if (episode.unlock.type === "storyRead") {
    return Boolean(requiredStoryId) && hasReadStory(requiredStoryId);
  }
  if (episode.unlock.type === "storyReadAndSongPlayed") {
    return (
      Boolean(requiredStoryId) &&
      hasReadStory(requiredStoryId) &&
      hasPlayedSong(episode.unlock.song)
    );
  }
  if (episode.unlock.type === "boss3Unlocked") {
    return getSaveData().boss3Unlocked === true;
  }
  return false;
}

function clearLockedStoryMessage() {
  const messageEl = document.getElementById("lockedStoryMessage");
  if (!messageEl) return;

  messageEl.textContent = "";
  messageEl.classList.remove("visible");
}

function hasPlayedSong(songId) {
  const saveData = getSaveData();
  const songData = saveData[songId];

  if (!songData || typeof songData !== "object") return false;

  return Object.values(songData).some(record => record?.played === true);
}

function hasReadStory(storyId) {
  const saveData = getSaveData();
  return saveData.storyRead?.[storyId] === true;
}

function getPreviousStoryEpisode(chapterIndex, episodeIndex, isFragment = false) {
  const chapter = chapters[chapterIndex];
  const episodes = isFragment ? (chapter.fragmentEpisodes || []) : chapter.episodes;

  if (episodeIndex > 0) return episodes[episodeIndex - 1];
  if (isFragment && chapter.episodes.length > 0) return chapter.episodes.at(-1);

  for (let index = chapterIndex - 1; index >= 0; index--) {
    const previousEpisodes = chapters[index].episodes || [];
    if (previousEpisodes.length > 0) return previousEpisodes.at(-1);
  }

  return null;
}

function renderChapters() {

  const chapterList = document.getElementById("chapterList");
  chapterList.innerHTML = "";

  chapters.forEach((chapter, index) => {
    if (chapter.hidden) return;

    const button = document.createElement("button");
    button.classList.add("chapterButton");
    button.textContent = chapter.title;
    button.dataset.chapter = index;

    if (index === currentChapterIndex) {
      button.classList.add("selected");
    }

    button.addEventListener("click", () => {
      clearLockedStoryMessage();
      currentChapterIndex = index;
      localStorage.setItem(LAST_STORY_CHAPTER_KEY, String(currentChapterIndex));
      renderChapters();
      renderEpisodes();
      updateChapterBackground();
      startStoryBGM();
    });

    const frame = document.createElement("div");
    frame.classList.add("chapterButtonFrame");
    frame.appendChild(button);
    chapterList.appendChild(frame);
  });
  updateResearchRecordsButtonVisibility();
}

function renderEpisodes() {
  const chapter = chapters[currentChapterIndex];

  chapterTitle.textContent = chapter.title;
  episodeList.innerHTML = "";

  const fragmentList = document.getElementById("fragmentEpisodeList");
  if (fragmentList) {
    fragmentList.innerHTML = "";
    fragmentList.style.display = "none";
  }

  let episodeColumn = null;

  chapter.episodes.forEach((episode, index) => {
    const button = document.createElement("button");
    button.classList.add("episodeButton");
    button.innerHTML = `<span>${episode.title}</span>`;

    if (episode.buttonImage) {
      button.style.backgroundImage = `url("${episode.buttonImage}")`;
      button.style.backgroundSize = "100% 100%";
    }

    const previousEpisode = getPreviousStoryEpisode(currentChapterIndex, index);

    if (!isEpisodeUnlocked(episode, previousEpisode)) {
      button.classList.add("locked");

      button.addEventListener("click", () => {
        clearLockedStoryMessage();

        const messageEl = document.getElementById("lockedStoryMessage");
        if (messageEl) {
          messageEl.textContent =
            episode.unlock?.message || "このストーリーはまだ解禁されていません";
          messageEl.classList.add("visible");
        }
      });
    } else {
      button.addEventListener("click", () => {
        clearLockedStoryMessage();

        if (episode.id === "chapter3_episode12") {
          const saveData = getSaveData();
          const retryBoss3Challenge = getSong19MaxClearedDifficulty(saveData) < 2;
          if (retryBoss3Challenge) {
            saveData.boss3UnlockChallengePending = true;
            localStorage.setItem("rhythmGame", JSON.stringify(saveData));
            location.href = "title.html?boss3Retry=1";
            return;
          }
        }

        if (
          episode.id === "chapter2_episode4" &&
          getCurrentPartnerId() === "isabel"
        ) {
          runBoss2IntroSequence();
          return;
        }

        openEpisode(index);
      });
    }

    if (index % 7 === 0) {
      episodeColumn = document.createElement("div");
      episodeColumn.classList.add("episodeColumn");
      episodeList.appendChild(episodeColumn);
    }

    episodeColumn.appendChild(button);
  });

  if (fragmentList) {
    const fragments = chapter.fragmentEpisodes || [];

    if (fragments.length > 0) {
      fragmentList.style.display = "flex";

      fragments.forEach((episode, index) => {
        const button = document.createElement("button");
        button.classList.add("episodeButton");
        button.innerHTML = `<span>${episode.title}</span>`;

        if (episode.buttonImage) {
          button.style.backgroundImage = `url("${episode.buttonImage}")`;
          button.style.backgroundSize = "100% 100%";
        }

        const previousEpisode = getPreviousStoryEpisode(currentChapterIndex, index, true);

        if (!isEpisodeUnlocked(episode, previousEpisode)) {
          button.classList.add("locked");

          button.addEventListener("click", () => {
            clearLockedStoryMessage();

            const messageEl = document.getElementById("lockedStoryMessage");
            if (messageEl) {
              messageEl.textContent =
                episode.unlock?.message || "このストーリーはまだ解禁されていません";
              messageEl.classList.add("visible");
            }
          });
        } else {
          button.addEventListener("click", () => {
            clearLockedStoryMessage();
            openFragmentEpisode(index);
          });
        }

        fragmentList.appendChild(button);
      });
    }
  }
}

function parseStoryScript(script) {
  const tokens = [];
  const regex = /(\[[\s\S]*?\]|\{[\s\S]*?\})/g;
  let match;

  while ((match = regex.exec(script)) !== null) {
    const raw = match[0];

    if (raw.startsWith("[")) {
      tokens.push({
        type: "text",
        text: raw
          .slice(1, -1)
          .trim()
          .split("/")
          .map(line => line.trim())
          .join("\n")
      });
    } else if (raw.startsWith("{")) {
      tokens.push({
        type: "command",
        command: raw.slice(1, -1).trim()
      });
    }
  }

  return tokens;
}

function updateStoryTextPosition(text) {
  const previousText = storyText.textContent;

  storyText.style.visibility = "hidden";
  storyText.textContent = text;

  const textHeight = storyText.offsetHeight;
  const top = Math.max(48, (window.innerHeight - textHeight) / 2);

  storyText.style.top = top + "px";
  storyText.textContent = previousText;
  storyText.style.visibility = "";
}

function typeText(text) {
  clearInterval(typingTimer);

  if (Array.isArray(text)) {
    text = text.join("\n");
  }

  updateStoryTextPosition(text);

  fullText = text;
  storyText.textContent = "";
  isTyping = true;

  let index = 0;

  typingTimer = setInterval(() => {
    storyText.textContent += text[index];
    index++;

    if (index >= text.length) {
      clearInterval(typingTimer);
      isTyping = false;
    }
  }, 38);
}

function getEpisodeSteps(episode) {
  if (episode.script) return parseStoryScript(episode.script);

  if (episode.lines) {
    return episode.lines.map(line => ({
      type: "text",
      text: Array.isArray(line) ? line.join("\n") : line
    }));
  }

  return [];
}

function updateChapterBackground() {
  const chapter = chapters[currentChapterIndex];
  const bg = chapter.background || "assets/bg/select_bg.jpg";
  const storyBackground = document.getElementById("storyBackground");

  if (storyBackground) {
    const keepBoss4EventBlack = boss4EventStoryEntry
      && document.body.classList.contains("boss4EventStoryEntry");
    storyBackground.style.backgroundImage = keepBoss4EventBlack
      ? "none"
      : `url("${bg}")`;
  }
}

function getCurrentEpisode() {
  const chapter = chapters[currentChapterIndex];

  if (currentEpisodeSource === "fragment") {
    return chapter.fragmentEpisodes?.[currentEpisodeIndex];
  }

  return chapter.episodes[currentEpisodeIndex];
}

function resetStoryImage() {
  if (introImageFadeTimer) {
    clearTimeout(introImageFadeTimer);
    introImageFadeTimer = null;
  }
  introImageActive = false;
  introImageFading = false;
  const img = document.getElementById("storyIntroImage");
  if (!img) return;
  img.classList.remove("visible");
  img.classList.add("hidden");
  img.removeAttribute("src");
}

function openEpisode(index) {
  resetStoryImage();
  currentEpisodeSource = "normal";
  currentEpisodeIndex = index;
  currentLineIndex = 0;

  document.body.classList.add("readingMode");
  readingOverlay.classList.remove("hidden");
  document.getElementById("readingSkipButton").disabled = false;

  showCurrentStep();
}

function openFragmentEpisode(index) {
  resetStoryImage();
  currentEpisodeSource = "fragment";
  currentEpisodeIndex = index;
  currentLineIndex = 0;

  document.body.classList.add("readingMode");
  readingOverlay.classList.remove("hidden");
  document.getElementById("readingSkipButton").disabled = false;

  showCurrentStep();
}

function showStoryImage(src) {
  console.log("表示する画像:", src);

  const img = document.getElementById("storyIntroImage");
  if (!img) {
    currentLineIndex++;
    showCurrentStep();
    return;
  }

  introImageActive = true;
  introImageFading = false;

  storyText.textContent = "";
  updateReadingPrevButton();

  img.src = src;
  img.classList.remove("hidden");
  img.classList.remove("visible");

  requestAnimationFrame(() => {
    img.classList.add("visible");
  });
}

function closeEpisode() {
  clearInterval(typingTimer);
  resetStoryImage();
  storySkipRequested = false;

  readingOverlay.classList.add("hidden");
  document.body.classList.remove("readingMode");
  if (document.body.classList.contains("boss4EventStoryEntry")) {
    document.body.classList.remove("boss4EventStoryEntry");
    updateChapterBackground();
  }
  storyText.textContent = "";

  currentEpisodeIndex = null;
  currentLineIndex = 0;
  currentEpisodeSource = "normal";
  isTyping = false;

  startStoryBGM();
}

function markEpisodeRead() {
  const episode = getCurrentEpisode();
  if (!episode?.id) return;

  const saveData = getSaveData();

  if (!saveData.storyRead) {
    saveData.storyRead = {};
  }

  if (!saveData.storyFlags) {
    saveData.storyFlags = {};
  }

  saveData.storyRead[episode.id] = true;

  if (episode.id === "chapter1_episode4") {
    saveData.storyFlags.pendingCanonPartnerEvent = true;
  }

  if (episode.id === "chapter2_episode4") {
    saveData.storyFlags.song9ChallengeStarted = true;
  }

  if (!saveData.unlockedPartners || typeof saveData.unlockedPartners !== "object") {
    saveData.unlockedPartners = {};
  }

  const newlyUnlockedPartners = Object.entries(window.partners || {}).flatMap(([partnerId, partner]) => {
    if (partner.unlock?.type !== "storyRead" || partner.unlock.storyId !== episode.id) return [];
    if (saveData.unlockedPartners[partnerId] === true) return [];

    saveData.unlockedPartners[partnerId] = true;
    return [{ partnerId, name: partner.name, full: partner.full }];
  });

  localStorage.setItem("rhythmGame", JSON.stringify(saveData));

  showPartnerUnlockOverlays(newlyUnlockedPartners);
}

readingOverlay.addEventListener("click", () => {
  if (isAdvancingStory) return;
  if (currentEpisodeIndex === null) return;

  if (introImageActive) {
    if (introImageFading) return;

    const img = document.getElementById("storyIntroImage");
    introImageFading = true;

    img.classList.remove("visible");

    introImageFadeTimer = setTimeout(() => {
      introImageFadeTimer = null;
      img.classList.add("hidden");
      introImageActive = false;
      introImageFading = false;

      currentLineIndex++;
      showCurrentStep();
    }, 550);

    return;
  }

  // 文字送り中なら全文表示
  if (isTyping) {
    clearInterval(typingTimer);
    storyText.textContent = fullText;
    isTyping = false;
    return;
  }

  currentLineIndex++;
  showCurrentStep();
});

document.getElementById("readingBackButton").addEventListener("click", (e) => {
  e.stopPropagation();
  closeEpisode();
});

document.getElementById("readingSkipButton").addEventListener("click", (event) => {
  event.stopPropagation();
  if (currentEpisodeIndex === null || storySkipRequested) return;
  event.currentTarget.disabled = true;

  clearInterval(typingTimer);
  isTyping = false;
  storyText.textContent = "";
  resetStoryImage();
  storySkipRequested = true;

  if (isAdvancingStory) return;
  const episode = getCurrentEpisode();
  currentLineIndex = getEpisodeSteps(episode).length;
  storySkipRequested = false;
  showCurrentStep();
});

function updateReadingPrevButton() {
  const prevButton = document.getElementById("readingPrevButton");
  if (!prevButton) return;

  if (currentLineIndex > 0 && currentEpisodeIndex !== null) {
    prevButton.classList.add("visible");
  } else {
    prevButton.classList.remove("visible");
  }
}

document.getElementById("readingPrevButton").addEventListener("click", (e) => {
  e.stopPropagation();

  if (currentEpisodeIndex === null) return;
  if (currentLineIndex <= 0) return;

  currentLineIndex--;
  showCurrentStep();
});

let storyBGM = null;
let currentBgmSrc = null;
let bgmFadeTimer = null;
let bgmTransitionToken = 0;

const STORY_BGM2_START_CHAPTER_INDEX = chapters.findIndex(
  chapter => chapter.title === "硝子越しの残響"
);

function getDefaultStoryBgmSrc(chapterIndex = currentChapterIndex) {
  return STORY_BGM2_START_CHAPTER_INDEX >= 0
    && chapterIndex >= STORY_BGM2_START_CHAPTER_INDEX
    ? "sounds/story_bgm2.mp3"
    : "sounds/story_bgm.mp3";
}

function startStoryBGM() {
  playStoryBGM(getDefaultStoryBgmSrc(), 0.45);
}

function stopStoryBGM(fadeMs = 900) {
  if (!storyBGM) return;

  bgmTransitionToken++;

  if (bgmFadeTimer) {
    clearInterval(bgmFadeTimer);
    bgmFadeTimer = null;
  }

  const audio = storyBGM;
  const startVolume = audio.volume;
  const intervalMs = 50;
  const steps = Math.max(1, Math.ceil(fadeMs / intervalMs));
  let currentStep = 0;

  bgmFadeTimer = setInterval(() => {
    currentStep++;

    const progress = currentStep / steps;
    audio.volume = Math.max(0, startVolume * (1 - progress));

    if (currentStep >= steps) {
      clearInterval(bgmFadeTimer);
      bgmFadeTimer = null;

      audio.pause();
      audio.currentTime = 0;
      audio.volume = startVolume;

      if (storyBGM === audio) {
        storyBGM = null;
        currentBgmSrc = null;
      }
    }
  }, intervalMs);
}

window.addEventListener("DOMContentLoaded", () => {
  // 4-11先頭のbgm:stop実行後に、DOMContentLoaded側からBGMを
  // 起動してしまわないよう、boss4イベント直結時は無音を維持する。
  if (boss4EventStoryEntry) return;
  if (["chapter3_episode12", "chapter3_episode13"].includes(requestedEpisodeId)) return;
  startStoryBGM();
});

function playStoryBGM(src = getDefaultStoryBgmSrc(), volume = 0.45, fadeMs = 700) {
  if (storyBGM && currentBgmSrc === src && !storyBGM.paused) {
    storyBGM.volume = volume;
    return;
  }

  const transitionToken = ++bgmTransitionToken;
  if (bgmFadeTimer) {
    clearInterval(bgmFadeTimer);
    bgmFadeTimer = null;
  }

  const beginNewTrack = () => {
    if (transitionToken !== bgmTransitionToken) return;

    const audio = new Audio(src);
    storyBGM = audio;
    currentBgmSrc = src;
    audio.loop = true;
    audio.volume = fadeMs > 0 ? 0 : volume;

    audio.play().catch(() => {
      document.addEventListener("click", () => {
        if (transitionToken === bgmTransitionToken && storyBGM === audio) {
          audio.play().catch(() => {});
        }
      }, { once: true });
    });

    if (fadeMs <= 0) return;
    const intervalMs = 50;
    const steps = Math.max(1, Math.ceil(fadeMs / intervalMs));
    let currentStep = 0;
    bgmFadeTimer = setInterval(() => {
      if (transitionToken !== bgmTransitionToken) {
        clearInterval(bgmFadeTimer);
        bgmFadeTimer = null;
        return;
      }
      currentStep++;
      audio.volume = Math.min(volume, volume * (currentStep / steps));
      if (currentStep >= steps) {
        clearInterval(bgmFadeTimer);
        bgmFadeTimer = null;
      }
    }, intervalMs);
  };

  const previousAudio = storyBGM;
  if (!previousAudio || previousAudio.paused || fadeMs <= 0) {
    if (previousAudio) {
      previousAudio.pause();
      previousAudio.currentTime = 0;
    }
    beginNewTrack();
    return;
  }

  const startVolume = previousAudio.volume;
  const intervalMs = 50;
  const steps = Math.max(1, Math.ceil(fadeMs / intervalMs));
  let currentStep = 0;
  bgmFadeTimer = setInterval(() => {
    if (transitionToken !== bgmTransitionToken) {
      clearInterval(bgmFadeTimer);
      bgmFadeTimer = null;
      return;
    }
    currentStep++;
    previousAudio.volume = Math.max(0, startVolume * (1 - currentStep / steps));
    if (currentStep >= steps) {
      clearInterval(bgmFadeTimer);
      bgmFadeTimer = null;
      previousAudio.pause();
      previousAudio.currentTime = 0;
      beginNewTrack();
    }
  }, intervalMs);
}

function waitMs(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

function playBoss2Riser() {
  const sound = new Audio("sounds/riser.mp3");
  sound.volume = 0.85;
  sound.play().catch(() => { });
}

function playSong35Riser() {
  const sound = new Audio("sounds/song35riser.mp3");
  sound.volume = 0.85;
  sound.play().catch(() => { });
}

function spawnBoss2LightParticles() {
  const area = document.getElementById("boss2LightParticles");
  if (!area) return;

  area.innerHTML = "";

  const width = window.innerWidth;
  const height = window.innerHeight;

  for (let i = 0; i < 48; i++) {
    const particle = document.createElement("div");
    particle.classList.add("boss2LightParticle");

    const x = Math.random() * width;
    const y = Math.random() * height;

    particle.style.left = x + "px";
    particle.style.top = y + "px";

    particle.style.setProperty("--x", x + "px");
    particle.style.setProperty("--y", y + "px");

    particle.style.animationDelay = Math.random() * 0.45 + "s";

    area.appendChild(particle);
  }
}

function playCanonGlowStartSound() {
  const sound = new Audio("sounds/canon_glow_start.mp3");
  sound.volume = 0.8;
  sound.play().catch(() => { });
}

async function runBoss2IntroSequence() {
  stopStoryBGM(700);

  const overlay = document.getElementById("boss2IntroOverlay");
  const image = document.getElementById("boss2IntroImage");
  if (!overlay || !image) return;

  document.body.classList.remove("whiteFlashOut");
  document.body.classList.remove("readingMode");

  if (readingOverlay) {
    readingOverlay.classList.add("hidden");
  }

  if (storyText) {
    storyText.textContent = "";
  }

  overlay.classList.remove(
    "hidden",
    "whiteFlash",
    "fadeToBlack",
    "lightGather",
    "whiteDissolve"
  );

  image.className = "";
  image.src = "";
  image.style.opacity = "0";
  image.style.transform = "scale(1)";

  overlay.classList.add("fadeToBlack");

  await waitMs(900);

  overlay.classList.remove("fadeToBlack");

  image.className = "";
  image.src = "images/story/2_3.png";
  image.style.opacity = "0";
  image.style.transform = "scale(1)";

  await waitMs(250);

  image.classList.add("fadeIn");

  await waitMs(2300);

  overlay.classList.remove("whiteFlash");
  void overlay.offsetWidth;
  overlay.classList.add("whiteFlash");
  playCanonGlowStartSound();

  await waitMs(100);

  image.className = "";
  image.src = "images/story/2_3_after.png";
  image.style.opacity = "1";
  image.style.transform = "scale(1)";

  playBoss2Riser();

  await waitMs(1300);

  image.classList.add("zoomIn");

  await waitMs(2600);

  overlay.classList.add("lightGather");
  spawnBoss2LightParticles();

  await waitMs(2600);

  overlay.classList.add("whiteDissolve");

  await waitMs(1200);

  overlay.classList.remove("lightGather");

  const centerGlow = document.getElementById("boss2CenterGlow");
  if (centerGlow) {
    centerGlow.style.opacity = "0";
  }

  overlay.classList.add("fadeToBlack");

  await waitMs(1300);

  showBoss2DifficultySelect();
}

function showBoss2DifficultySelect() {
  const overlay = document.getElementById("boss2DifficultyOverlay");
  const buttons = document.querySelectorAll("#boss2DifficultyButtons button");

  if (!overlay) return;

  overlay.classList.remove("hidden");
  overlay.classList.remove("fadeOut");

  buttons.forEach(button => {
    button.onclick = () => {
      const difficulty = button.dataset.difficulty;

      const startSound = new Audio("sounds/startsound.mp3");
      startSound.play().catch(() => { });

      overlay.classList.add("fadeOut");

      setTimeout(() => {
        location.href =
          `game.html?song=boss2&difficulty=${difficulty}&storyChallenge=1&boss2Challenge=1&skipStoryIntro=1`;
      }, 650);
    };
  });
}

async function runStoryCommand(command) {
  const parts = command.split(":");
  const name = parts[0];

  if (name === "bgm" && parts[1] === "stop") {
    const fadeMs = Number(parts[2] || 900);
    stopStoryBGM(fadeMs);
    return;
  }

  if (name === "bgm" && parts[1] === "play") {
    const src = parts[2] || "sounds/story_bgm.mp3";
    const volume = Number(parts[3] || 0.45);
    playStoryBGM(src, volume);
    return;
  }

  if (name === "wait") {
    const ms = Number(parts[1] || 0);
    await waitMs(ms);
    return;
  }
}

let isAdvancingStory = false;
let storySkipRequested = false;

async function showCurrentStep() {
  if (isAdvancingStory) return;
  isAdvancingStory = true;

  const episode = getCurrentEpisode();
  const steps = getEpisodeSteps(episode);

  if (storySkipRequested) {
    currentLineIndex = steps.length;
    storySkipRequested = false;
  }

  while (currentLineIndex < steps.length) {
    const step = steps[currentLineIndex];

    if (step.type === "command") {
      const command = step.command;

      if (command.startsWith("image:")) {
        const src = command.slice("image:".length).trim();
        showStoryImage(src);
        isAdvancingStory = false;
        return;
      }

      await runStoryCommand(command);
      if (storySkipRequested) {
        currentLineIndex = steps.length;
        storySkipRequested = false;
        continue;
      }
      currentLineIndex++;
      continue;
    }

    typeText(step.text);
    updateReadingPrevButton();
    isAdvancingStory = false;
    return;
  }

  markEpisodeRead();

  if (episode.id === "chapter1_episode6") {
    const fade = document.getElementById("storyIntroFade");
    if (fade) {
      fade.classList.remove("fadeIn");
      fade.classList.add("fadeOut");
    }

    setTimeout(() => {
      location.href = "title.html?endingDemo=1";
    }, 900);

    return;
  }

  if (episode.id === "chapter2_episode4") {
    stopStoryBGM(900);
    document.body.classList.add("whiteFlashOut");

    setTimeout(() => {
      showSong9DifficultySelect();
    }, 900);

    return;
  }

  if (episode.id === "chapter4_episode10") {
    runSong35CrystalTransition();
    return;
  }

  if (episode.id === "chapter4_episode11") {
    runToBeContinuedSequence();
    return;
  }

  if (episode.id === "chapter3_episode11") {
    stopStoryBGM(800);

    const fade = document.getElementById("storyIntroFade");
    if (fade) {
      fade.classList.remove("fadeIn");
      fade.classList.add("fadeOut");
    }

    setTimeout(() => {
      location.href = "game.html?song=song18&bulletChallenge=1";
    }, 900);

    return;
  }

  if (episode.id === "chapter3_episode12") {
    stopStoryBGM(0);
    const fade = document.getElementById("storyIntroFade");
    if (fade) {
      fade.classList.remove("fadeIn");
      fade.classList.add("fadeOut");
    }

    setTimeout(() => {
      location.href = "game.html?song=boss3&difficulty=0&boss3Intro=1";
    }, 900);

    return;
  }

  if (episode.id === "chapter3_episode13") {
    stopStoryBGM(800);
    beginStoryCredits(2800);

    return;
  }

  if (episode.id === "chapter4_episode6") {
    stopStoryBGM(900);
    document.body.classList.add("whiteFlashOut");

    setTimeout(() => {
      showSong9DifficultySelect("song33");
    }, 900);

    return;
  }

  closeEpisode();
  renderEpisodes();
  isAdvancingStory = false;
}

async function runToBeContinuedSequence() {
  const overlay = document.getElementById("toBeContinuedOverlay");
  const textElement = document.getElementById("toBeContinuedTyped");

  if (!overlay || !textElement) {
    closeEpisode();
    renderEpisodes();
    isAdvancingStory = false;
    return;
  }

  stopStoryBGM(900);
  document.body.classList.add("toBeContinuedPlaying");
  textElement.textContent = "";
  overlay.classList.remove("hidden", "visible", "leaving");

  void overlay.offsetWidth;
  overlay.classList.add("visible");

  await waitMs(1050);

  const message = "TO BE CONTINUED";
  for (const character of message) {
    const characterElement = document.createElement("span");
    characterElement.className = "toBeContinuedCharacter";
    characterElement.textContent = character;
    textElement.appendChild(characterElement);
    await waitMs(character === " " ? 180 : 135);
  }

  await waitMs(1450);

  closeEpisode();
  renderEpisodes();
  document.body.classList.remove("toBeContinuedPlaying");
  overlay.classList.add("leaving");

  await waitMs(1200);

  overlay.classList.add("hidden");
  overlay.classList.remove("visible", "leaving");
  textElement.textContent = "";
  isAdvancingStory = false;
}

let storyChallengeTargetSongId = "song9";

function showSong9DifficultySelect(songId = "song9") {
  const overlay = document.getElementById("song9DifficultyOverlay");
  if (!overlay) return;

  storyChallengeTargetSongId = songId;
  song9DifficultySelected = false;

  const fractureButton = overlay.querySelector(
    '#song9DifficultyButtons button[data-difficulty="2"]'
  );
  if (fractureButton) {
    fractureButton.classList.toggle("hidden", songId !== "song35");
  }
  overlay.classList.toggle("song35Difficulty", songId === "song35");

  document.body.classList.remove("whiteFlashOut");
  overlay.classList.remove("fadeOut");
  overlay.classList.remove("hidden");
}

function spawnSong35CrystalNotes() {
  const container = document.getElementById("song35CrystalNotes");
  if (!container) return;

  container.innerHTML = "";
  const symbols = ["♪", "♫", "♩", "♬"];

  for (let i = 0; i < 34; i++) {
    const note = document.createElement("span");
    const angle = Math.random() * Math.PI * 2;
    const distance = 34 + Math.random() * 48;

    note.className = "song35CrystalNote";
    note.textContent = symbols[i % symbols.length];
    note.style.setProperty("--note-x", `${Math.cos(angle) * distance}vw`);
    note.style.setProperty("--note-y", `${Math.sin(angle) * distance}vh`);
    note.style.setProperty("--note-delay", `${Math.random() * 0.42}s`);
    note.style.setProperty("--note-size", `${14 + Math.random() * 20}px`);
    note.style.setProperty("--note-rotate", `${-80 + Math.random() * 160}deg`);
    container.appendChild(note);
  }
}

async function runSong35CrystalTransition() {
  const transition = document.getElementById("song35CrystalTransition");
  if (!transition) {
    showSong9DifficultySelect("song35");
    return;
  }

  stopStoryBGM(700);
  document.body.classList.add("song35CrystalPlaying");

  transition.classList.remove(
    "hidden",
    "crystalVisible",
    "crystalBurst",
    "revealDifficulty"
  );
  spawnSong35CrystalNotes();

  void transition.offsetWidth;
  await waitMs(250);
  playSong35Riser();
  transition.classList.add("crystalVisible");

  await waitMs(850);
  transition.classList.add("crystalBurst");

  await waitMs(1550);
  showSong9DifficultySelect("song35");

  await waitMs(180);
  transition.classList.add("revealDifficulty");

  await waitMs(900);
  transition.classList.add("hidden");
  transition.classList.remove(
    "crystalVisible",
    "crystalBurst",
    "revealDifficulty"
  );
}

